PROCEDURE gradeToLetter(score)
{
   IF(score ≥ 90)
   {
      RETURN("A")
   }
   ELSE
   {
      IF(score ≥ 80)
      {
         RETURN("B")
      }
      ELSE
      {
         RETURN("C or below")
      }
   }
}

